case "${1:-}" in
  init) shift; cmd_init "$@";;
  run) shift; cmd_run "$@";;
  resume) shift; cmd_resume "$@";;
  post) shift; cmd_post "$@";;
  board) shift; cmd_board "$@";;
  review) shift; cmd_review "$@";;
  ask) shift; cmd_ask "$@";;
  usage) cmd_usage;;
  -h|--help|"") usage;;
  *) die "unknown command $1";;
esac

case "${1:-}" in
  init) shift; cmd_init "$@";;
  run) shift; cmd_run "$@";;
  resume) shift; cmd_resume "$@";;
  post) shift; cmd_post "$@";;
  board) shift; cmd_board "$@";;
  review) shift; cmd_review "$@";;
  ask) shift; cmd_ask "$@";;
  usage) cmd_usage;;
  -h|--help|"") usage;;
  *) die "unknown command $1";;
esac

cmd_ask() { # [--cwd DIR] [--model M] [--timeout S] [--write] "prompt"
  local cwd="$PWD" model="gpt-6-sol" tmo=900 write=0 prompt=""
  while (($#)); do
    case $1 in
      --cwd) cwd=$2; shift 2;; --model) model=$2; shift 2;; --timeout) tmo=$2; shift 2;;
      --write) write=1; shift;; -*) die "unknown flag $1";; *) prompt=$1; shift;;
    esac
  done
  [[ -n $prompt ]] || { usage; exit 2; }
